import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 8 — a FULL-LENGTH adaptive digital SAT form (original,
 * hand-verified items). Each module carries the official count: Reading &
 * Writing modules have 27 questions, Math modules have 22. Module 2 comes in
 * an easier and a harder variant for adaptive routing. Topics and passages are
 * distinct from Practice Tests 1–7 and 9.
 */

// ════════════════════════ READING & WRITING — MODULE 1 (27, mixed) ════════════════════════
const T8_RW_M1: SatQuestion[] = [
  { id: "t8rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The diplomat's remarks were carefully ______, designed to soothe both sides without committing to either position.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["measured", "reckless", "hostile", "spontaneous"], correct: 0, explanation: "The remarks are described as 'carefully ______' and as 'designed to soothe both sides without committing to either position.' The blank must name a quality consistent with careful, restrained, non-committal speech. 'Measured' means deliberate and controlled, exactly matching 'carefully' and the goal of not committing — correct. 'Reckless' (B) means careless and rash, the opposite of 'carefully.' 'Hostile' (C) means aggressively unfriendly, which would inflame rather than 'soothe both sides.' 'Spontaneous' (D) means unplanned and impulsive, contradicting 'carefully' and the deliberate aim of avoiding commitment." },
  { id: "t8rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The flock of geese ______ across the gray autumn sky every morning.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["fly", "flies", "have flown", "are flying"], correct: 1, explanation: "Rule: a verb must agree in number with its grammatical subject, and a collective noun like 'flock' is singular even when followed by 'of geese.' The subject is 'The flock' (singular), and the time marker 'every morning' calls for the simple present, so the singular present verb 'flies' is correct. 'Fly' (A) is the plural present form, which would agree with 'geese' but not with the true subject 'flock.' 'Have flown' (C) is plural present-perfect and also fails singular agreement, while the perfect tense clashes with the habitual 'every morning.' 'Are flying' (D) is plural ('are') and the progressive aspect again misfits the habitual marker 'every morning.'" },
  { id: "t8rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Octopuses can change both the color and texture of their skin in under a second, blending into coral, sand, or rock to evade predators.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Octopuses rapidly alter their skin to camouflage themselves.", "Octopuses can only change color, never texture.", "Octopuses are easily spotted by predators.", "Octopuses take hours to blend into their surroundings."], correct: 0, explanation: "The text says octopuses change 'both the color and texture of their skin in under a second, blending into coral, sand, or rock to evade predators.' The main idea must capture the rapid skin change used for camouflage — choice A restates exactly that. B is wrong because the text explicitly says they change 'both the color AND texture,' not color only. C is contradicted by the passage: the camouflage lets them 'evade predators,' so they are hard to spot, not easily spotted. D reverses the timing — the text says 'in under a second,' not hours." },
  { id: "t8rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The bridge had stood for over a century. ______, engineers recommended a full inspection before reopening it to traffic.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Even so", "For instance", "Likewise", "In short"], correct: 0, explanation: "The first sentence states the bridge 'had stood for over a century' (a point for confidence); the second says engineers nonetheless 'recommended a full inspection.' The relationship is concession — caution persists despite the bridge's long endurance — which 'Even so' signals. 'For instance' (B) introduces an example, but the inspection is not an example of the bridge's longevity. 'Likewise' (C) signals similarity, yet the two sentences contrast rather than parallel each other. 'In short' (D) introduces a summary, but the second sentence adds a new recommendation rather than summarizing the first." },
  { id: "t8rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The expedition packed only the essentials ______ rope, a tent, and a week of rations.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["essentials, rope", "essentials: rope", "essentials; rope", "essentials rope"], correct: 1, explanation: "Rule: a colon follows a complete independent clause to introduce a list or explanation. 'The expedition packed only the essentials' is a complete sentence, and 'rope, a tent, and a week of rations' is the list that specifies those essentials, so the colon in choice B is correct. A comma (A) is too weak to introduce a formal list after a complete clause and would create a run-on/comma-splice feel. A semicolon (C) must join two independent clauses, but 'rope, a tent, and a week of rations' is not a clause. No punctuation (D) leaves the list fused to the sentence with no boundary, which is incorrect." },
  { id: "t8rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her early sketches were merely ______, rough outlines she would later develop into finished paintings.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["preliminary", "definitive", "polished", "final"], correct: 0, explanation: "The sketches are called 'merely ______, rough outlines she would later develop into finished paintings.' The blank must describe early, unfinished work that precedes a finished version. 'Preliminary' means coming before the main or finished stage — a perfect fit for 'rough outlines' developed 'later.' 'Definitive' (B) means final and authoritative, the opposite of rough early work. 'Polished' (C) means refined and complete, contradicting 'rough.' 'Final' (D) also means last/finished, which clashes with the idea that she 'would later develop' them into the finished paintings." },
  { id: "t8rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The grant funds research proposals submitted by faculty only; proposals from undergraduate students are not eligible.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A proposal written by an undergraduate cannot receive the grant.", "Only undergraduates may apply for the grant.", "Every proposal submitted is automatically funded.", "Faculty are barred from applying."], correct: 0, explanation: "The text says the grant funds proposals 'submitted by faculty only' and that 'proposals from undergraduate students are not eligible.' Logically, if undergraduate proposals are ineligible, one cannot receive the grant — choice A follows directly. B reverses the rule: faculty, not undergraduates, may apply. C is unsupported — the text describes eligibility, never says every proposal is 'automatically funded.' D contradicts the text, which says funding is for faculty 'only,' so faculty are the ones eligible, not barred." },
  { id: "t8rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The startup doubled its revenue this year. ______, it cut its operating costs by nearly a third.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "At the same time", "In contrast", "Otherwise"], correct: 1, explanation: "Both sentences report good news: the startup 'doubled its revenue' and 'cut its operating costs by nearly a third.' These are two positive achievements occurring together, so an additive transition like 'At the same time' fits. 'Nevertheless' (A) signals contrast/concession, but the second fact reinforces rather than opposes the first. 'In contrast' (C) also marks opposition, yet rising revenue and falling costs point the same favorable direction. 'Otherwise' (D) means 'if not / in other respects,' implying a condition or alternative that the sentence does not set up." },
  { id: "t8rw1-9", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Each of the volunteers ______ asked to bring a signed permission form to the orientation.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["were", "are", "was", "have been"], correct: 2, explanation: "Rule: 'each' is a singular indefinite pronoun and takes a singular verb, even when followed by 'of the [plural noun].' The subject is 'Each' (singular), and the past-time context ('asked to bring … to the orientation') calls for singular past 'was.' 'Were' (A) is plural past — wrong number, mismatched with singular 'Each.' 'Are' (B) is plural present — wrong number and wrong tense. 'Have been' (D) is plural present perfect — wrong number ('Each' needs 'has been') and the perfect aspect doesn't fit the simple past framing." },
  { id: "t8rw1-10", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The senator's speech was praised for its ______ tone, treating opponents with unexpected courtesy.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["gracious", "scornful", "indifferent", "aggressive"], correct: 0, explanation: "The blank describes a tone 'praised' for 'treating opponents with unexpected courtesy.' The word must mean courteous and kind — 'gracious' means polite, generous, and kind, matching 'courtesy' exactly. 'Scornful' (B) means contemptuous, the opposite of courteous and not something one praises here. 'Indifferent' (C) means uncaring or detached, which doesn't capture active courtesy toward opponents. 'Aggressive' (D) means hostile and forceful, contradicting the courteous treatment the sentence highlights." },
  { id: "t8rw1-11", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A survey found that residents who walked to work reported higher satisfaction with their commute than those who drove, even when their travel times were similar.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["Walking commuters reported greater satisfaction than driving commuters of comparable commute length.", "Driving was always faster than walking.", "Commute time was the only factor that mattered.", "All residents preferred to drive."], correct: 0, explanation: "The survey found walkers 'reported higher satisfaction … than those who drove, even when their travel times were similar.' Choice A restates this directly — higher satisfaction for walkers at comparable commute lengths. B is unsupported: the passage says nothing about driving being faster; it holds travel times 'similar.' C is contradicted — the finding shows mode (walking vs. driving) affected satisfaction independently of time, so time was not the only factor. D reverses the result, since walkers, not drivers, reported greater satisfaction; the text never says all residents preferred driving." },
  { id: "t8rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The recipe calls for fresh basil. ______, dried basil may be substituted in a pinch.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Consequently", "Indeed"], correct: 1, explanation: "The first sentence states the ideal ingredient ('fresh basil'); the second offers a fallback ('dried basil may be substituted in a pinch') that runs counter to that ideal. This contrast/qualification calls for 'However.' 'Therefore' (A) and 'Consequently' (C) both signal cause-and-effect, but the substitution is not a consequence of calling for fresh basil — it's an alternative to it. 'Indeed' (D) signals emphasis or confirmation of the prior point, yet the second sentence qualifies rather than reinforces the first." },
  { id: "t8rw1-13", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The museum, which opened in 1899 ______ still attracts thousands of visitors each week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["1899 still", "1899, still", "1899; still", "1899: still"], correct: 1, explanation: "Rule: a nonrestrictive 'which' clause must be set off by a pair of commas. The sentence already opens that clause with a comma after 'museum' ('The museum, which opened in 1899 ___ still attracts …'), so the clause must be closed with the matching comma after '1899' before the main verb 'attracts' resumes — choice B. No punctuation (A) leaves the inserted clause unclosed, jamming it into the main clause. A semicolon (C) would require an independent clause on each side, but 'still attracts thousands …' is the predicate of the main clause, not a separate sentence. A colon (D) would wrongly signal that a list or explanation follows." },
  { id: "t8rw1-14", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The river's ______ course made navigation difficult, winding back on itself again and again.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meandering", "straight", "direct", "narrow"], correct: 0, explanation: "The blank is defined by the trailing description 'winding back on itself again and again,' and the course 'made navigation difficult.' 'Meandering' means following a winding, curving path — a precise match. 'Straight' (B) is the opposite of winding and would make navigation easier, not harder. 'Direct' (C) likewise means going the shortest/straightest way, contradicting 'winding back on itself.' 'Narrow' (D) describes width, not the winding shape the sentence specifies, so it doesn't fit the supporting detail." },
  { id: "t8rw1-15", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Researchers noted that coral reefs recover faster when nearby fish populations remain large, because the fish graze on algae that would otherwise smother new coral.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Healthy fish populations aid reef recovery by controlling algae.", "Fish destroy coral reefs by eating them.", "Algae help coral grow more quickly.", "Reefs recover regardless of fish."], correct: 0, explanation: "The text says reefs 'recover faster when nearby fish populations remain large, because the fish graze on algae that would otherwise smother new coral.' The main idea is that abundant fish help recovery by eating the harmful algae — choice A. B misreads the mechanism: the fish eat algae, not the coral, and they help rather than destroy the reef. C reverses the algae's role — algae 'would otherwise smother new coral,' so they harm, not help, coral. D contradicts the central claim that fish populations make a difference to recovery." },
  { id: "t8rw1-16", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory installed new filters to reduce pollution. ______, complaints from neighbors about air quality dropped sharply.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nonetheless", "As a result", "In contrast", "For example"], correct: 1, explanation: "The first sentence states a cause ('installed new filters to reduce pollution'); the second states its effect ('complaints … dropped sharply'). A cause-and-effect link calls for 'As a result.' 'Nonetheless' (A) signals concession/contrast, but the drop in complaints follows logically from cleaner air rather than opposing it. 'In contrast' (C) also marks opposition, which misfits the consistent cause-effect chain. 'For example' (D) introduces an illustration of a prior idea, but fewer complaints is a consequence, not an example, of installing filters." },
  { id: "t8rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "By the time the rescue team arrived, the hikers ______ already found their way back to the trailhead.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["have", "had", "has", "will have"], correct: 1, explanation: "Rule: the past perfect ('had' + past participle) marks an action completed before another past event. Here the hikers 'had already found their way back' before the past event 'the rescue team arrived,' so 'had' is correct. 'Have' (A) is present perfect, which links a past action to the present, not to an earlier past event. 'Has' (C) is also present perfect and additionally is singular, disagreeing with the plural subject 'hikers.' 'Will have' (D) is future perfect, placing the action in the future, which contradicts the past-time frame 'By the time the rescue team arrived.'" },
  { id: "t8rw1-18", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The professor's lectures were notoriously ______, packing three textbooks' worth of material into a single hour.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["dense", "sparse", "leisurely", "shallow"], correct: 0, explanation: "The blank is explained by the following detail: lectures 'packing three textbooks' worth of material into a single hour.' Cramming that much content into so little time makes them 'dense' (densely packed with information). 'Sparse' (B) means thin or scanty — the opposite of packing in lots of material. 'Leisurely' (C) means unhurried and slow-paced, which contradicts squeezing three textbooks into one hour. 'Shallow' (D) means superficial in depth; the sentence stresses sheer quantity of material, not lack of depth, so it doesn't match the cue." },
  { id: "t8rw1-19", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The new policy applies to part-time employees who have worked at least six months; those hired more recently are not yet covered.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A part-time worker hired last week is not yet covered by the policy.", "All part-time workers are immediately covered.", "Only full-time workers are covered.", "Workers of seven months are excluded."], correct: 0, explanation: "The policy covers part-timers 'who have worked at least six months,' and 'those hired more recently are not yet covered.' A worker hired last week clearly has under six months' tenure, so by the rule they are not yet covered — choice A. B is contradicted by the six-month threshold, which excludes newer hires from immediate coverage. C misstates the policy, which applies to part-time employees, not only full-time ones. D is wrong because seven months exceeds the six-month minimum, so such a worker would be covered, not excluded." },
  { id: "t8rw1-20", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail map was outdated and confusing. ______, many visitors got lost on their way to the falls.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Even so", "Consequently", "By contrast", "For instance"], correct: 1, explanation: "The first sentence gives a cause ('The trail map was outdated and confusing'); the second gives its effect ('many visitors got lost'). A cause-and-effect link calls for 'Consequently.' 'Even so' (A) signals concession/contrast, but getting lost follows from the bad map rather than happening in spite of it. 'By contrast' (C) marks opposition, which misfits a straightforward cause-effect chain. 'For instance' (D) introduces an example of a prior idea, but the visitors getting lost is a result of the poor map, not an illustration of it." },
  { id: "t8rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The chef seasoned the soup, plated the dish, and ______ it to the waiting table.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["carrying", "carries", "carried", "to carry"], correct: 2, explanation: "Rule: items in a series must be parallel in form. The series is 'seasoned the soup, plated the dish, and ______ it' — the first two are simple past-tense verbs, so the third must match: 'carried.' 'Carrying' (A) is a present participle, breaking parallel structure with 'seasoned' and 'plated.' 'Carries' (B) is present tense, clashing with the past-tense series and the past narrative. 'To carry' (D) is an infinitive, which is not parallel with the finite past verbs in the list." },
  { id: "t8rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Walking through the gallery, ______ caught the visitor's eye immediately.", prompt: "Which choice avoids a dangling modifier?", type: "mcq", choices: ["the bright mural", "the visitor saw the bright mural that", "there was a bright mural that", "a bright mural"], correct: 1, explanation: "Rule: an introductory participial phrase must logically modify the subject that immediately follows it. 'Walking through the gallery' can only describe a person, so the subject must be 'the visitor.' Choice B makes 'the visitor' the subject who was walking and 'saw the bright mural,' correctly attaching the modifier. A ('the bright mural') makes the mural the thing walking through the gallery — a dangling modifier, since murals don't walk. C ('there was a bright mural that') has the empty expletive 'there' as subject, so nothing is doing the walking — still dangling. D ('a bright mural') has the same flaw as A, illogically making the mural the walker." },
  { id: "t8rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Although she had trained for the marathon for months, the runner approached the starting line with a calm she had not expected to feel.", prompt: "Which choice best describes the runner's state at the starting line?", type: "mcq", choices: ["surprisingly composed", "deeply anxious", "wholly unprepared", "openly fearful"], correct: 0, explanation: "The text says the runner reached the line 'with a calm she had not expected to feel.' 'Surprisingly composed' captures both the calm ('composed') and the unexpectedness ('surprisingly') — choice A. B ('deeply anxious') contradicts the explicit word 'calm.' C ('wholly unprepared') is contradicted by 'she had trained for the marathon for months,' so she was well prepared. D ('openly fearful') also opposes 'calm' and is unsupported by any cue of fear in the sentence." },
  { id: "t8rw1-24", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The committee debated the proposal for hours. ______, no final decision was reached that evening.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "In the end", "For example", "Similarly"], correct: 1, explanation: "The first sentence describes a long process ('debated the proposal for hours'); the second states its final outcome ('no final decision was reached that evening'). 'In the end' fits this summary-of-outcome relationship. 'Therefore' (A) signals a logical consequence, but reaching no decision is the result of time running out, not a deduction the debate compels. 'For example' (C) introduces an illustration, yet the second sentence reports the result, not an example. 'Similarly' (D) signals likeness, but the two sentences are sequential (process then outcome), not parallel cases." },
  { id: "t8rw1-25", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The two scientists shared the prize, but ______ contributions were quite different in nature.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["there", "their", "they're", "its"], correct: 1, explanation: "Rule: 'their' is the plural possessive pronoun. The sentence needs a possessive to show the contributions belong to 'The two scientists' (plural), so 'their contributions' is correct. 'There' (A) indicates place or is an expletive, not a possessive. 'They're' (C) is the contraction of 'they are' ('they are contributions were' is ungrammatical). 'Its' (D) is singular possessive and cannot refer to two scientists; number disagreement makes it wrong." },
  { id: "t8rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The editorial's argument rested on a single ______ assumption: that readers already agreed with its conclusion.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unexamined", "proven", "trivial", "shared"], correct: 0, explanation: "The assumption is one the editorial simply takes for granted — 'that readers already agreed with its conclusion' — without testing it. 'Unexamined' means accepted without scrutiny, exactly that flaw. 'Proven' (B) means demonstrated to be true, the opposite of an untested assumption. 'Trivial' (C) means unimportant, but the sentence stresses that the whole argument 'rested on' this assumption, making it crucial, not trivial. 'Shared' (D) would imply the agreement actually exists, yet the point is that the editorial merely assumes agreement rather than establishing it." },
  { id: "t8rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Whereas the older textbook presents history as a list of dates, this edition organizes events around the people who shaped them.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast two textbooks' approaches to organizing history.", "To argue that dates do not matter at all.", "To summarize the older textbook with approval.", "To list the events covered in the new edition."], correct: 0, explanation: "The sentence is built on the contrast word 'Whereas': 'the older textbook presents history as a list of dates,' but 'this edition organizes events around the people.' The purpose is to contrast the two textbooks' organizing approaches — choice A. B overstates: the text contrasts methods but never argues dates 'do not matter at all.' C is wrong because the older textbook is contrasted, not summarized with approval. D misses the point — the text describes the new edition's approach, not a list of the specific events it covers." },
];

// ════════════════════════ READING & WRITING — MODULE 2 EASY (27) ════════════════════════
const T8_RW_M2E: SatQuestion[] = [
  { id: "t8rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The cake was so ______ that everyone asked for a second slice.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["delicious", "stale", "burnt", "plain"], correct: 0, explanation: "The cause-effect cue 'so ______ that everyone asked for a second slice' means the blank must describe a cake people love. 'Delicious' (tasting very good) explains why everyone wanted more — correct. 'Stale' (B, dry and old) would discourage a second slice. 'Burnt' (C, overcooked) also would not make people ask for more. 'Plain' (D, dull/unremarkable) is too weak to justify everyone wanting seconds." },
  { id: "t8rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The students ______ ready for the field trip this morning.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Rule: subject-verb agreement requires a plural verb with a plural subject. 'The students' is plural, and 'this morning' fits the present, so the plural present verb 'are' is correct. 'Is' (A) is singular present — disagrees with plural 'students.' 'Was' (C) is singular past — wrong number and shifts to past tense. 'Am' (D) is the first-person singular form for 'I,' which cannot pair with 'students.'" },
  { id: "t8rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Penguins are birds, but they cannot fly; instead, they use their wings to swim swiftly through the water.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Penguins use their wings to swim rather than fly.", "Penguins can fly long distances.", "Penguins are a kind of fish.", "Penguins never enter the water."], correct: 0, explanation: "The text says penguins 'cannot fly; instead, they use their wings to swim swiftly through the water.' Choice A captures this main idea exactly. B is directly contradicted — the passage says they 'cannot fly.' C is wrong because the text calls penguins 'birds,' not fish. D contradicts 'swim swiftly through the water,' which shows they do enter the water." },
  { id: "t8rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The library was about to close. ______, we hurried to check out our books.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "So", "For example", "Meanwhile"], correct: 1, explanation: "The first sentence gives a reason ('The library was about to close'); the second gives the resulting action ('we hurried to check out our books'). 'So' signals this cause-and-result link. 'However' (A) marks contrast, but hurrying is a logical response to the closing, not a contradiction of it. 'For example' (C) introduces an illustration, yet the hurry is a consequence, not an example. 'Meanwhile' (D) signals simultaneous unrelated action, but the two events are causally connected, not merely concurrent." },
  { id: "t8rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday she ______ a letter to her grandmother.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["write", "writes", "wrote", "writing"], correct: 2, explanation: "Rule: a time marker fixes the tense. 'Yesterday' places the action in the past, so the simple past 'wrote' is correct. 'Write' (A) is base/present and clashes with 'yesterday.' 'Writes' (B) is present tense (and third-person singular), again wrong for a past time. 'Writing' (D) is a participle that cannot stand alone as the main verb without a helping verb ('was writing')." },
  { id: "t8rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The room was very ______, so we turned on more lights.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["dark", "bright", "loud", "warm"], correct: 0, explanation: "The cause-effect cue 'so ______, so we turned on more lights' means the blank explains why lights were needed. A 'dark' room is the logical reason to turn on lights — correct. 'Bright' (B) is the opposite; a bright room needs no extra lights. 'Loud' (C) describes sound, which has nothing to do with turning on lights. 'Warm' (D) describes temperature, also unrelated to needing more light." },
  { id: "t8rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Recycling saves energy, reduces waste, and helps protect natural resources.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Recycling has several benefits.", "Recycling wastes energy.", "Recycling only reduces waste.", "Recycling harms resources."], correct: 0, explanation: "The text lists three positives: recycling 'saves energy, reduces waste, and helps protect natural resources.' Choice A generalizes these into 'several benefits.' B contradicts 'saves energy' — recycling conserves, not wastes, energy. C says 'only reduces waste,' ignoring the two other listed benefits. D contradicts 'helps protect natural resources,' so recycling protects rather than harms them." },
  { id: "t8rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He waited for ______ hour before the bus finally came.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "Rule: use 'an' before a word that begins with a vowel SOUND, not just a vowel letter. 'Hour' has a silent 'h' and starts with the vowel sound /aʊ/, so 'an hour' is correct. 'A' (A) is used before consonant sounds and is wrong before the vowel sound in 'hour.' 'The only' (C) changes the meaning to a specific, sole hour, which the sentence ('waited for ___ hour') does not support. 'Some' (D) is vague and unidiomatic here ('waited for some hour' is awkward and shifts meaning)." },
  { id: "t8rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The math problem was ______, so she solved it quickly.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["easy", "hard", "long", "strange"], correct: 0, explanation: "The cause-effect cue 'so she solved it quickly' means the blank explains the quick solution. An 'easy' problem is naturally solved quickly — correct. 'Hard' (B) is the opposite and would slow her down, not speed her up. 'Long' (C) implies more steps and more time, contradicting 'quickly.' 'Strange' (D, unfamiliar/odd) would more likely cause hesitation than a fast solution." },
  { id: "t8rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My brother ______ his bike to school every day.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["ride", "rides", "riding", "to ride"], correct: 1, explanation: "Rule: a third-person singular subject in the present tense takes a verb ending in -s. 'My brother' is singular, and the habitual marker 'every day' calls for the simple present, so 'rides' is correct. 'Ride' (A) is the plural/base form, which disagrees with singular 'brother.' 'Riding' (C) is a participle and needs a helping verb to be a complete predicate. 'To ride' (D) is an infinitive, which cannot serve as the sentence's main verb." },
  { id: "t8rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Plants need sunlight, water, and good soil to grow strong and healthy.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Plants need several things to grow well.", "Plants grow best in the dark.", "Plants do not need water.", "Plants need only soil."], correct: 0, explanation: "The text lists three requirements: plants 'need sunlight, water, and good soil to grow strong and healthy.' Choice A generalizes these into 'several things.' B contradicts the need for 'sunlight' — plants do not grow best in the dark. C contradicts 'water,' which is explicitly listed as a need. D says 'only soil,' ignoring sunlight and water, so it omits two listed needs." },
  { id: "t8rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "It was cold outside. ______, I wore my warmest coat.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Meanwhile"], correct: 1, explanation: "The first sentence gives a cause ('It was cold outside'); the second gives the result ('I wore my warmest coat'). 'Therefore' signals this cause-and-effect link. 'However' (A) marks contrast, but wearing a warm coat agrees with the cold rather than opposing it. 'For example' (C) introduces an illustration, yet the coat is a response, not an example. 'Meanwhile' (D) indicates simultaneous unrelated events, but here the two ideas are causally linked." },
  { id: "t8rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The dog wagged ______ tail when its owner came home.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["it's", "its", "their", "they're"], correct: 1, explanation: "Rule: 'its' is the singular possessive pronoun. The tail belongs to one dog, so 'its tail' is correct. 'It's' (A) is the contraction 'it is' ('it is tail' is nonsense). 'Their' (C) is plural possessive, but a single dog requires a singular pronoun. 'They're' (D) is the contraction 'they are,' which is both wrong in number and not possessive." },
  { id: "t8rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The river moved ______, barely seeming to flow at all.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["slowly", "quickly", "loudly", "wildly"], correct: 0, explanation: "The blank is defined by the trailing detail 'barely seeming to flow at all,' which describes very little motion. 'Slowly' matches that near-stillness — correct. 'Quickly' (B) is the opposite of barely flowing. 'Loudly' (C) describes sound, not the speed of flow the cue specifies. 'Wildly' (D) implies fast, turbulent motion, contradicting 'barely seeming to flow.'" },
  { id: "t8rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The store gives a free gift to every customer who spends more than $50.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A customer who spends $60 receives a free gift.", "Every customer gets a free gift.", "Gifts cost $50 each.", "No customers receive gifts."], correct: 0, explanation: "The rule is a free gift for 'every customer who spends more than $50.' Since $60 is more than $50, that customer qualifies — choice A follows directly. B overgeneralizes: only customers spending over $50 get a gift, not 'every' customer. C invents a detail — the text never says gifts cost $50; $50 is the spending threshold, not a price. D contradicts the text, which clearly states qualifying customers do receive gifts." },
  { id: "t8rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "We ______ to the beach last weekend.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["go", "goes", "went", "going"], correct: 2, explanation: "Rule: the time marker sets the tense. 'Last weekend' places the action in the past, so the simple past 'went' is correct. 'Go' (A) is present/base and clashes with the past-time cue. 'Goes' (B) is present third-person singular — wrong tense and also wrong number for 'We.' 'Going' (D) is a participle and cannot be the main verb without a helping verb ('were going')." },
  { id: "t8rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "She practiced the piano every day. ______, she became a skilled player.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Eventually", "Instead", "Meanwhile"], correct: 1, explanation: "The first sentence describes a sustained effort over time ('practiced the piano every day'); the second states the eventual outcome ('she became a skilled player'). 'Eventually' captures that the skill developed gradually as a result. 'However' (A) signals contrast, but becoming skilled agrees with daily practice rather than opposing it. 'Instead' (C) implies a replacement or alternative, which the sentence does not set up. 'Meanwhile' (D) marks simultaneous unrelated action, but the skill is the result of the practice, not a concurrent event." },
  { id: "t8rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The crowd was ______ and cheered loudly for the team.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["excited", "bored", "tired", "silent"], correct: 0, explanation: "The blank is supported by the detail 'and cheered loudly for the team.' Loud cheering shows enthusiasm, so 'excited' fits. 'Bored' (B) contradicts loud cheering, which signals engagement, not boredom. 'Tired' (C) suggests low energy, the opposite of cheering loudly. 'Silent' (D) directly contradicts the crowd making loud noise." },
  { id: "t8rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The team ______ practicing hard for the championship.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["are", "is", "were", "am"], correct: 1, explanation: "Rule: a collective noun like 'team' takes a singular verb when treated as a single unit. The sentence treats the team as one group acting together ('practicing hard'), and the present progressive needs the singular helping verb 'is.' 'Are' (A) is plural present, disagreeing with the singular collective subject. 'Were' (C) is past tense and plural, mismatching both number and the present action. 'Am' (D) is the first-person form for 'I,' which cannot pair with 'team.'" },
  { id: "t8rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Ice is simply water that has frozen solid when the temperature drops below freezing.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Ice forms when water freezes in cold temperatures.", "Ice is always warmer than water.", "Ice cannot melt.", "Ice is not made of water."], correct: 0, explanation: "The text says ice is 'water that has frozen solid when the temperature drops below freezing.' Choice A restates this: water freezes into ice in cold temperatures. B is illogical and unsupported — ice forms in cold, so it isn't warmer than water. C is not stated and is false in spirit; the text describes freezing, not an inability to melt. D directly contradicts the passage, which says ice IS water that has frozen." },
  { id: "t8rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The bakery sells bread and pastries. ______, it offers coffee in the morning.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Also", "Instead", "Otherwise"], correct: 1, explanation: "The first sentence lists products ('sells bread and pastries'); the second adds another ('offers coffee in the morning'). An additive transition like 'Also' fits this 'one more thing' relationship. 'However' (A) marks contrast, but adding coffee does not oppose selling bread and pastries. 'Instead' (C) implies replacement, yet the coffee is in addition to, not in place of, the baked goods. 'Otherwise' (D) means 'if not / in other respects,' setting up a condition the sentence does not contain." },
  { id: "t8rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "______ going to the concert with us tonight?", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["Who's", "Whose", "Whom", "Who"], correct: 0, explanation: "Rule: 'Who's' is the contraction of 'who is.' The sentence needs a subject plus a 'be' verb for the progressive: 'Who is going …?' so 'Who's' is correct. 'Whose' (B) is the possessive ('whose coat?') and leaves no verb for 'going.' 'Whom' (C) is the object form and cannot be the subject of 'going'; it also supplies no verb. 'Who' (D) is the right subject pronoun but without 'is' the sentence lacks the helping verb the progressive 'going' requires." },
  { id: "t8rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The story had a ______ ending that made everyone smile.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["happy", "sad", "scary", "boring"], correct: 0, explanation: "The blank is supported by the result 'that made everyone smile.' Smiling signals a pleasing conclusion, so 'happy' fits. 'Sad' (B) would prompt tears, not smiles. 'Scary' (C) would cause fear, not smiles. 'Boring' (D) would leave people uninterested rather than smiling." },
  { id: "t8rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Brushing your teeth twice a day helps prevent cavities and keeps your gums healthy.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Brushing twice daily protects teeth and gums.", "Brushing harms the teeth.", "Brushing only matters once a year.", "Brushing has no benefits."], correct: 0, explanation: "The text says brushing 'twice a day helps prevent cavities and keeps your gums healthy.' Choice A captures both benefits — protecting teeth (preventing cavities) and gums. B contradicts the passage, which says brushing helps, not harms. C misstates the frequency: the text says twice a day, not once a year. D contradicts the clearly listed benefits of preventing cavities and keeping gums healthy." },
  { id: "t8rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The children played outside ______ it started to rain.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["until", "and until", "until, when", "because until"], correct: 0, explanation: "Rule: a single subordinating conjunction joins the clauses without redundancy. 'Until' links the activity to the moment it stopped — 'played outside until it started to rain' — and is correct. 'And until' (B) is redundant, pairing the coordinator 'and' with the subordinator 'until.' 'Until, when' (C) doubles up two connectors and adds an unneeded comma, creating a faulty construction. 'Because until' (D) jams two conjunctions with conflicting meanings (cause vs. time) together, which is ungrammatical." },
  { id: "t8rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The movie got great reviews. ______, the theater was packed on opening night.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "Instead", "Otherwise"], correct: 1, explanation: "The first sentence gives a cause ('The movie got great reviews'); the second gives the effect ('the theater was packed'). 'As a result' signals this cause-and-effect link. 'However' (A) marks contrast, but a packed theater agrees with great reviews rather than opposing them. 'Instead' (C) implies a replacement, which the sentence does not set up. 'Otherwise' (D) means 'if not,' introducing a condition absent from the sentence." },
  { id: "t8rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The instructions were ______ and easy to follow.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "confusing", "long", "missing"], correct: 0, explanation: "The blank is paired with 'and easy to follow,' so it must agree in meaning with that quality. 'Clear' (easy to understand) matches 'easy to follow' — correct. 'Confusing' (B) is the opposite and contradicts 'easy to follow.' 'Long' (C) describes length, not clarity, and doesn't reinforce ease of following. 'Missing' (D) means absent, which can't be 'easy to follow' since there would be nothing to follow." },
];

// ════════════════════════ READING & WRITING — MODULE 2 HARD (27) ════════════════════════
const T8_RW_M2H: SatQuestion[] = [
  { id: "t8rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic's praise was so ______ that readers struggled to tell whether she admired the book or quietly disdained it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["equivocal", "effusive", "blunt", "scathing"], correct: 0, explanation: "The blank is defined by its result: 'readers struggled to tell whether she admired the book or quietly disdained it.' Praise so ambiguous that its real stance is unclear is 'equivocal' (open to two interpretations). 'Effusive' (B) means gushing and unrestrained — that would make her admiration obvious, not hard to read. 'Blunt' (C) means direct and plain-spoken, the opposite of ambiguous. 'Scathing' (D) means harshly critical, which would signal clear disdain, again removing the uncertainty the sentence describes." },
  { id: "t8rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The essay opens with an anecdote that seems trivial, but by its close the author has revealed the anecdote to embody her entire thesis.", prompt: "Which choice best describes the function of the opening anecdote?", type: "mcq", choices: ["It appears minor but ultimately illustrates the essay's central claim.", "It states the essay's conclusion outright.", "It contradicts the author's thesis.", "It serves only as decoration with no later relevance."], correct: 0, explanation: "The text says the anecdote 'seems trivial, but by its close the author has revealed the anecdote to embody her entire thesis.' Its function is to look minor at first yet finally illustrate the central claim — choice A. B is wrong because the anecdote does not 'state … outright'; its thesis-bearing role is only 'revealed' later. C reverses the relationship — the anecdote embodies the thesis rather than contradicting it. D is contradicted by 'embody her entire thesis,' which makes the anecdote highly relevant, not mere decoration." },
  { id: "t8rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study measured plant growth under different light colors: 12 cm under red light, 19 cm under blue light, and 20 cm under combined red-and-blue light.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Most of the growth benefit was achieved by blue light alone.", "Red light produced the tallest plants.", "Combined light cut growth in half.", "Light color made no difference to growth."], correct: 0, explanation: "The data: red 12 cm, blue 19 cm, combined 20 cm. Moving from red to blue adds 7 cm, while adding red to blue light adds only 1 cm more (19 to 20). So blue light alone delivers nearly all of the benefit that combined light provides — choice A. B is wrong because red light produced the SHORTEST plants (12 cm), not the tallest. C is contradicted by the numbers: combined light gave the most growth (20 cm), not half. D is false — growth clearly varied with light color (12 vs. 19 vs. 20 cm)." },
  { id: "t8rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The treaty resolved the immediate border dispute. ______, it left untouched the deeper resentments that had fueled the conflict for decades.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "The first sentence reports a success ('resolved the immediate border dispute'); the second reports an offsetting limitation ('left untouched the deeper resentments'). This contrast between surface resolution and lingering problems calls for 'However.' 'Therefore' (A) and 'Accordingly' (D) both signal a consequence, but the unresolved resentments are not a result that follows from settling the border. 'Likewise' (C) signals similarity, yet the two sentences oppose each other (solved vs. unsolved) rather than running parallel." },
  { id: "t8rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship offers students the chance to conduct research, to present findings, and ______ with industry experts.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["networking", "to network", "networks", "networked"], correct: 1, explanation: "Rule: items joined in a series must share the same grammatical form. The list is 'to conduct research, to present findings, and ______ with industry experts' — the first two are infinitives, so the third must be the infinitive 'to network.' 'Networking' (A) is a gerund/participle, breaking the parallel infinitive structure. 'Networks' (C) is a finite present-tense verb, not parallel with the infinitives. 'Networked' (D) is a past-tense/participle form, again not matching 'to conduct' and 'to present.'" },
  { id: "t8rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the author's prose is dense with allusion, demanding careful rereading on every page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["accessible", "intricate", "demanding", "layered"], correct: 0, explanation: "The construction 'Far from being ______' negates the blank, so the word must describe what the prose is NOT. Since the prose is in fact 'dense with allusion, demanding careful rereading,' the blank should name the opposite: 'accessible' (easy to understand). 'Intricate' (B) means complex — that describes the prose as it is, so 'far from being intricate' would contradict 'dense.' 'Demanding' (C) literally appears as a true trait of the prose, so it can't be what the prose is 'far from being.' 'Layered' (D) likewise means rich and multi-leveled, matching the dense prose rather than opposing it." },
  { id: "t8rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "While earlier economists treated rising prices as a sign of prosperity, the author argues that the same trend can mask deepening inequality.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To challenge an earlier view by reinterpreting the same economic trend.", "To agree fully with earlier economists.", "To define the term inflation.", "To deny that prices ever rise."], correct: 0, explanation: "The text contrasts what 'earlier economists' believed (rising prices = prosperity) with the author's argument that 'the same trend can mask deepening inequality.' The purpose is to challenge the older view by reinterpreting the identical trend — choice A. B is the opposite: the author disputes, not agrees with, the earlier economists. C is wrong — the passage never sets out to define 'inflation.' D mischaracterizes the argument; the author accepts that prices rise and reinterprets what that rise signifies, rather than denying it." },
  { id: "t8rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Neither the lead researcher nor her assistants ______ aware that the samples had been mislabeled.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "Rule (proximity): with 'neither … nor,' the verb agrees with the nearer subject. The nearer subject is plural 'assistants,' so the plural verb 'were' is correct; the past context ('the samples had been mislabeled') also calls for past tense. 'Was' (A) is singular and would agree only with a singular nearer subject. 'Is' (C) is singular and present, wrong on both number and tense. 'Has been' (D) is singular present perfect — wrong number for plural 'assistants' and the wrong aspect for the simple past narrative." },
  { id: "t8rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The negotiator's ______ tone — never rising, never yielding — wore down the opposition over the long session.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unrelenting", "erratic", "timid", "fleeting"], correct: 0, explanation: "The blank is defined by the appositive 'never rising, never yielding' and by the fact that the tone 'wore down the opposition over the long session.' A tone that never yields and steadily grinds opponents down is 'unrelenting' (relentless, persistent). 'Erratic' (B) means inconsistent and unpredictable, contradicting 'never rising, never yielding' (which signals steadiness). 'Timid' (C) means shy and easily intimidated, the opposite of a tone that wears down opposition. 'Fleeting' (D) means brief and passing, clashing with a tone sustained over a 'long session.'" },
  { id: "t8rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The historian cautions that surviving records favor the powerful, since the poor rarely left written accounts of their own.", prompt: "Which choice best states the historian's point?", type: "mcq", choices: ["The written record is skewed toward the powerful.", "The poor wrote most surviving documents.", "All social classes are equally documented.", "Written records are entirely reliable."], correct: 0, explanation: "The historian says 'surviving records favor the powerful, since the poor rarely left written accounts of their own.' This is exactly a bias toward the powerful — choice A. B reverses the point: the poor 'rarely' wrote, so they did not produce most documents. C contradicts the claim of imbalance — the classes are NOT equally documented. D overstates reliability; the historian's whole point is that the record is skewed, i.e., not a complete or unbiased picture." },
  { id: "t8rw2h-11", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine proved effective in trials. ______, distributing it to remote regions posed logistical challenges no one had fully anticipated.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Hence", "Still", "Therefore", "Likewise"], correct: 1, explanation: "The first sentence reports a success ('proved effective in trials'); the second reports an unexpected obstacle ('distributing it … posed logistical challenges'). This concessive contrast — success despite a remaining problem — calls for 'Still.' 'Hence' (A) and 'Therefore' (C) both signal a consequence, but the logistical challenges are not a result that effectiveness causes. 'Likewise' (D) signals similarity, yet the two sentences oppose each other (success vs. difficulty) rather than echo each other." },
  { id: "t8rw2h-12", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The director, along with the entire cast, ______ thanked the audience after the final performance.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["have", "were", "has", "having"], correct: 2, explanation: "Rule: a phrase set off by commas with 'along with' is parenthetical and does not change the number of the subject. The true subject is the singular 'director,' so the singular 'has thanked' is correct. 'Have' (A) is plural and would wrongly agree with 'cast' rather than 'director.' 'Were' (B) is plural and shifts to a passive/linking sense, breaking the 'thanked' construction and the singular agreement. 'Having' (D) is a participle that leaves the sentence with no finite main verb." },
  { id: "t8rw2h-13", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The poem's imagery is deliberately ______, refusing any single interpretation and inviting endless debate.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["polyvalent", "literal", "transparent", "simplistic"], correct: 0, explanation: "The blank is defined by 'refusing any single interpretation and inviting endless debate,' i.e., imagery open to many meanings. 'Polyvalent' literally means having many values or interpretations — a precise match. 'Literal' (B) means taking words at face value with one plain meaning, the opposite of resisting a single interpretation. 'Transparent' (C) means clear and easily understood, which contradicts imagery that sparks 'endless debate.' 'Simplistic' (D) means oversimplified, again clashing with imagery rich enough to support many readings." },
  { id: "t8rw2h-14", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a memory test, participants recalled 8 of 20 items with no review, 15 with one review, and 16 with two reviews.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The first review produced by far the largest recall gain.", "Reviewing hurt recall.", "Two reviews doubled the recall of one review.", "Review had no effect on recall."], correct: 0, explanation: "The data: 8 items with no review, 15 with one review, 16 with two. The first review raises recall from 8 to 15 (+7), while the second raises it only from 15 to 16 (+1). So the first review yields by far the biggest gain — choice A. B is contradicted: recall rose with review (8 to 15 to 16), so reviewing helped. C is false — two reviews (16) did not double one review (15); 16 is far from 30. D is contradicted by the clear increases, showing review did affect recall." },
  { id: "t8rw2h-15", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The new law promised sweeping reform. ______, its narrow definitions left most affected workers outside its protections.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In practice", "Therefore", "Likewise", "As a result"], correct: 0, explanation: "The first sentence states a promise ('promised sweeping reform'); the second states the disappointing reality ('its narrow definitions left most affected workers outside its protections'). 'In practice' sets a promise against the actual outcome — the needed contrast. 'Therefore' (B) and 'As a result' (D) signal consequence, but failing to protect workers is not the logical result of promising reform; it undercuts that promise. 'Likewise' (C) signals similarity, yet the promise and the outcome diverge rather than match." },
  { id: "t8rw2h-16", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The data ______ collected over three years, but the analysis took only a few months to complete.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "are"], correct: 1, explanation: "Two rules combine here. (1) In formal usage 'data' is plural, so it takes a plural verb. (2) The second clause ('the analysis took only a few months') is past tense, so for consistent tense the verb should be past. The plural past form is 'were' — choice B. 'Was' (A) is singular past, violating the plural-'data' convention tested here. 'Is' (C) is singular present — wrong number and wrong tense. 'Are' (D) is plural but present tense, clashing with the past-tense 'took' in the companion clause." },
  { id: "t8rw2h-17", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The reviewer admired the building's ______ design, in which every ornament served a structural purpose.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["economical", "ostentatious", "haphazard", "cluttered"], correct: 0, explanation: "The blank is defined by 'every ornament served a structural purpose' — nothing is wasted or merely decorative. 'Economical' (efficient, free of waste) captures a design in which each element does real work. 'Ostentatious' (B) means showy and excessive, the opposite of a design with no wasted ornament. 'Haphazard' (C) means random and disorganized, contradicting the purposeful integration described. 'Cluttered' (D) means crowded with excess, again clashing with a design where every part serves a function." },
  { id: "t8rw2h-18", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her model oversimplifies, yet maintains that its predictions match the data better than any rival.", prompt: "Which choice best describes the author's stance?", type: "mcq", choices: ["She defends the model's usefulness despite acknowledging its limits.", "She rejects the model entirely.", "She claims the model is flawless.", "She refuses to compare it with rivals."], correct: 0, explanation: "The text says she 'concedes that her model oversimplifies, yet maintains that its predictions match the data better than any rival.' That is a defense of the model's usefulness while admitting a limitation — choice A. B is wrong because she 'maintains' the model's value rather than rejecting it. C is contradicted by her concession that it 'oversimplifies,' so she does not call it flawless. D is contradicted by 'better than any rival,' which is exactly a comparison with rivals." },
  { id: "t8rw2h-19", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The renovation preserved the building's historic facade. ______, its interior was rebuilt entirely with modern materials.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Inside, by contrast,", "Likewise,", "As a result,"], correct: 1, explanation: "The first sentence says the renovation 'preserved the building's historic facade' (kept old); the second says the 'interior was rebuilt entirely with modern materials' (made new). The exterior-vs-interior, old-vs-new opposition calls for 'Inside, by contrast.' 'Therefore' (A) and 'As a result' (D) signal consequence, but rebuilding the interior is not a result of preserving the facade. 'Likewise' (C) signals similarity, yet preserving and rebuilding are opposite treatments, not parallel ones." },
  { id: "t8rw2h-20", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The startup's founders, ______ had met in college, built their first product in a rented garage.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["who", "whom", "which", "whose"], correct: 0, explanation: "Rule: choose the relative pronoun by its role in its own clause, and use 'who' for people acting as the subject. In '______ had met in college,' the pronoun is the subject performing 'had met,' so the subject form 'who' is correct. 'Whom' (B) is the object form and cannot serve as the subject of 'had met.' 'Which' (C) refers to things, not people like 'founders.' 'Whose' (D) is possessive and would need a noun to own (e.g., 'whose college'), which the clause does not provide." },
  { id: "t8rw2h-21", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than resolving the mystery, the final chapter ______ it, raising new questions in place of answers.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["compounds", "dispels", "clarifies", "simplifies"], correct: 0, explanation: "The sentence sets up a contrast with 'Rather than resolving the mystery,' and the chapter is 'raising new questions in place of answers.' The blank must mean the opposite of resolving — to deepen or add to the mystery. 'Compounds' means to intensify or add to, a perfect fit. 'Dispels' (B) means to clear away/drive off, which is closer to resolving, contradicting 'Rather than resolving.' 'Clarifies' (C) means to make clear, again the opposite of raising new questions. 'Simplifies' (D) means to make easier or plainer, which conflicts with adding new puzzles." },
  { id: "t8rw2h-22", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Unlike accounts that credit the invention to a lone genius, this biography stresses the network of collaborators whose ideas made the breakthrough possible.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To reframe an invention as a collaborative achievement rather than a solo one.", "To name the single inventor responsible.", "To dismiss the breakthrough as unimportant.", "To praise lone-genius accounts."], correct: 0, explanation: "The sentence contrasts 'accounts that credit the invention to a lone genius' with this biography, which 'stresses the network of collaborators.' The purpose is to recast the invention as a group effort — choice A. B is the opposite emphasis; the biography downplays a single inventor in favor of many. C is unsupported — nothing dismisses the breakthrough as unimportant; it explains how it happened. D reverses the stance: the text contrasts with, rather than praises, lone-genius accounts." },
  { id: "t8rw2h-23", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The first engine stalled repeatedly ______ the redesigned model ran smoothly through every trial.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["stalled repeatedly, the", "stalled repeatedly; the", "stalled repeatedly the", "stalled repeatedly: the"], correct: 1, explanation: "Rule: two independent clauses may be joined by a semicolon (with no conjunction). 'The first engine stalled repeatedly' and 'the redesigned model ran smoothly through every trial' are both complete clauses, so the semicolon in choice B correctly links them. A comma alone (A) creates a comma splice between two independent clauses. No punctuation (C) produces a run-on/fused sentence. A colon (D) is for introducing a list or explanation that the first clause leads into, not for two coordinate, contrasting clauses." },
  { id: "t8rw2h-24", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The expedition gathered abundant samples. ______, poor weather forced the team to abandon its planned second site.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "Even so", "Likewise", "Therefore"], correct: 1, explanation: "The first sentence reports a success ('gathered abundant samples'); the second reports a setback ('poor weather forced the team to abandon its planned second site'). The setback occurs in spite of the success, a concessive contrast marked by 'Even so.' 'Consequently' (A) and 'Therefore' (D) signal consequence, but abandoning the second site is caused by the weather, not by the successful sampling. 'Likewise' (C) signals similarity, yet success and setback are opposing outcomes, not parallel ones." },
  { id: "t8rw2h-25", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir's tone is ______: the author mocks her younger self even as she defends the choices that self made.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["self-aware", "naive", "bitter", "detached"], correct: 0, explanation: "The blank is explained by the clause after the colon: 'the author mocks her younger self even as she defends the choices that self made.' Recognizing and gently critiquing one's past self while understanding it is a 'self-aware' tone. 'Naive' (B) means lacking insight or experience, the opposite of the reflective awareness shown. 'Bitter' (C) implies resentment, but she defends, rather than resents, her younger self's choices. 'Detached' (D) means emotionally distant, yet the author is closely, personally engaged with her own past — both mocking and defending it." },
  { id: "t8rw2h-26", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The geologist notes that the rock layers nearer the surface are younger, since each new deposit settles atop the ones already there.", prompt: "Which choice best states the geologist's point?", type: "mcq", choices: ["Higher rock layers tend to be more recent than lower ones.", "Deeper layers are always the youngest.", "All rock layers form at the same time.", "Rock layers cannot be dated by depth."], correct: 0, explanation: "The geologist says layers 'nearer the surface are younger, since each new deposit settles atop the ones already there.' So higher layers are more recent than lower ones — choice A. B reverses this: deeper layers are older, not the youngest. C contradicts the stated sequence, in which layers form one atop another over time, not simultaneously. D is contradicted by the very principle described — depth does indicate relative age." },
  { id: "t8rw2h-27", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having reviewed every applicant's file, ______ a decision before the deadline.", prompt: "Which choice avoids a dangling modifier?", type: "mcq", choices: ["a decision was reached by the committee", "the committee reached", "there was a decision", "the deadline forced a decision"], correct: 1, explanation: "Rule: the introductory participial phrase 'Having reviewed every applicant's file' must modify the subject that follows it, and that subject must be the agent who did the reviewing — the committee. Choice B makes 'the committee' the subject ('the committee reached a decision'), correctly attaching the modifier. A is passive ('a decision was reached'), making 'a decision' the subject — but a decision can't review files, so it dangles. C ('there was a decision') uses the expletive 'there' as subject, leaving no one to have reviewed the files. D ('the deadline forced a decision') makes 'the deadline' the subject, but the deadline did not review the files — also dangling." },
];

// ════════════════════════ MATH — MODULE 1 (22, mixed) ════════════════════════
const T8_M_M1: SatQuestion[] = [
  { id: "t8m1-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x + 7 = 31, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve for x. Start with 4x + 7 = 31. Subtract 7 from both sides: 4x = 31 − 7 = 24. Divide both sides by 4: x = 24/4 = 6. Check: 4(6) + 7 = 24 + 7 = 31, which matches. Trap: forgetting to subtract the 7 first and computing 31/4 ≈ 7.75 gives the wrong value; the constant must be moved before dividing." },
  { id: "t8m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A recipe makes 18 cookies and serves 6 people equally. How many cookies does each person get?", type: "mcq", choices: ["3", "4", "6", "12"], correct: 0, explanation: "Goal: split 18 cookies equally among 6 people. Divide the total by the number of people: 18 ÷ 6 = 3 cookies each (choice A). Check: 6 people × 3 cookies = 18 cookies, the full batch. Trap: choice D (12) comes from multiplying or mis-dividing (18 − 6); choice C (6) confuses the number of people with the answer. Equal sharing is always total ÷ groups." },
  { id: "t8m1-3", section: "math", domain: "Algebra", difficulty: "med", prompt: "A line passes through (0, 2) and (3, 11). What is its slope?", type: "mcq", choices: ["3", "9", "1/3", "13"], correct: 0, explanation: "Goal: find the slope through (0, 2) and (3, 11). Slope = (change in y)/(change in x) = (y2 − y1)/(x2 − x1) = (11 − 2)/(3 − 0) = 9/3 = 3 (choice A). Check: starting at (0, 2) and rising 3 per unit x, at x = 3 we reach y = 2 + 3·3 = 11, matching the second point. Trap: choice B (9) is the rise alone without dividing by the run; choice C (1/3) inverts the ratio (run over rise); choice D (13) wrongly adds the coordinates." },
  { id: "t8m1-4", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = x² − 3x + 2, what is f(5)?", type: "mcq", choices: ["12", "10", "22", "8"], correct: 0, explanation: "Goal: evaluate f(x) = x^2 − 3x + 2 at x = 5. Substitute 5 for x: f(5) = 5^2 − 3(5) + 2 = 25 − 15 + 2. Compute left to right: 25 − 15 = 10, then 10 + 2 = 12 (choice A). Check: the terms are 25, −15, +2, summing to 12. Trap: choice C (22) drops the −3x term (25 − 3 + 2 type slip); choice B (10) stops at 25 − 15 and forgets to add 2." },
  { id: "t8m1-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has radius 5. What is its area? (Use π.)", type: "mcq", choices: ["25π", "10π", "5π", "50π"], correct: 0, explanation: "Goal: find the area of a circle with radius 5. Area = πr^2 = π(5)^2 = π(25) = 25π (choice A). Check: r = 5 squared is 25, times π. Trap: choice B (10π) uses the circumference idea or doubles the radius (2πr-style) instead of squaring; choice C (5π) forgets to square the radius; choice D (50π) wrongly multiplies the squared radius by 2." },
  { id: "t8m1-6", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 2(x − 4) = 3x − 5, what is the value of x?", type: "grid", gridAnswers: ["-3"], explanation: "Goal: solve for x. Distribute the left side: 2(x − 4) = 2x − 8, so the equation is 2x − 8 = 3x − 5. Subtract 2x from both sides: −8 = x − 5. Add 5 to both sides: −8 + 5 = x, so x = −3. Check: left = 2(−3 − 4) = 2(−7) = −14; right = 3(−3) − 5 = −9 − 5 = −14. Both equal −14. Trap: forgetting to distribute the 2 over both terms, or dropping the negative sign, leads to a wrong (often positive) answer." },
  { id: "t8m1-7", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A jacket originally priced at $80 is on sale for $60. By what percent was the price reduced?", type: "mcq", choices: ["25%", "20%", "33%", "15%"], correct: 0, explanation: "Goal: percent reduction from $80 to $60. Find the dollar drop: 80 − 60 = 20. Percent change = (amount of change)/(original) = 20/80 = 0.25 = 25% (choice A). Check: 25% of 80 is 0.25·80 = 20, and 80 − 20 = 60, the sale price. Trap: choice C (33%) divides the change by the NEW price (20/60 ≈ 33%) instead of the original; choice B (20%) confuses the dollar amount of the discount with the percent." },
  { id: "t8m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions of x² − 7x + 10 = 0?", type: "grid", gridAnswers: ["7"], explanation: "Goal: sum of the roots. Factor x^2 − 7x + 10: find two numbers that multiply to +10 and add to −7, namely −2 and −5, so (x − 2)(x − 5) = 0. The solutions are x = 2 and x = 5; their sum is 2 + 5 = 7. Shortcut/check: for x^2 + bx + c = 0, the sum of roots = −b = −(−7) = 7, confirming the answer. Trap: reporting the product (2·5 = 10) instead of the sum, or sign-flipping −b." },
  { id: "t8m1-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A right triangle has legs 9 and 12. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["15"], explanation: "Goal: find the hypotenuse using the Pythagorean theorem a^2 + b^2 = c^2. With legs 9 and 12: c^2 = 9^2 + 12^2 = 81 + 144 = 225. Take the positive square root: c = √225 = 15. Check: 9-12-15 is a 3-4-5 triangle scaled by 3 (3·3, 4·3, 5·3), confirming 15. Trap: adding the legs (9 + 12 = 21) instead of using the theorem, or forgetting to take the square root and answering 225." },
  { id: "t8m1-10", section: "math", domain: "Algebra", difficulty: "med", prompt: "The equation 3x + 2y = 12 is graphed in the xy-plane. What is the y-intercept?", type: "mcq", choices: ["6", "4", "12", "2"], correct: 0, explanation: "Goal: find the y-intercept of 3x + 2y = 12. The y-intercept occurs where x = 0. Substitute x = 0: 3(0) + 2y = 12, so 2y = 12, giving y = 6. The y-intercept is (0, 6), so the value is 6 (choice A). Check: the point (0, 6) satisfies 3·0 + 2·6 = 12. Trap: choice B (4) is the x-intercept (set y = 0: 3x = 12, x = 4); the question asks for the y-intercept, so x must be 0, not y." },
  { id: "t8m1-11", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of 4, 8, x, and 12 is 9. What is x?", type: "grid", gridAnswers: ["12"], explanation: "Goal: find x given a mean of 9 over 4 values. Mean = sum/count, so sum = mean × count = 9 × 4 = 36. The known values are 4 + 8 + 12 = 24, so 24 + x = 36. Subtract: x = 36 − 24 = 12. Check: the four numbers 4, 8, 12, 12 sum to 36, and 36/4 = 9. Trap: dividing 9 by 4 or forgetting there are 4 (not 3) values; the unknown x is itself one of the four terms in the sum." },
  { id: "t8m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If 2^x = 32, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "16"], correct: 0, explanation: "Goal: solve 2^x = 32. Rewrite 32 as a power of 2: 2, 4, 8, 16, 32 → that's 2^1, 2^2, 2^3, 2^4, 2^5, so 32 = 2^5. With the bases equal, set exponents equal: x = 5 (choice A). Check: 2^5 = 32. Trap: choice D (16) is 2^4, one doubling short of 32; choice B (4) confuses the exponent with the power 2^2 = 4. Count the doublings carefully." },
  { id: "t8m1-13", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x − 2y = 16 and y = 2, what is the value of x?", type: "mcq", choices: ["4", "3", "6", "2"], correct: 0, explanation: "Goal: find x given 5x − 2y = 16 and y = 2. Substitute y = 2: 5x − 2(2) = 16, so 5x − 4 = 16. Add 4 to both sides: 5x = 20. Divide by 5: x = 4 (choice A). Check: 5(4) − 2(2) = 20 − 4 = 16, matching. Trap: forgetting to multiply 2·2 = 4 (using just 2) gives 5x − 2 = 16 → x = 3.6; the coefficient on y must be applied to the substituted value." },
  { id: "t8m1-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 50° and 65°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["65"], explanation: "Goal: find the third angle. The interior angles of any triangle sum to 180°. Add the two known angles: 50 + 65 = 115. Subtract from 180: 180 − 115 = 65°. Check: 50 + 65 + 65 = 180, the required total. Trap: subtracting only one angle (180 − 65 = 115) or using 360° (the sum for a quadrilateral, not a triangle) gives a wrong result." },
  { id: "t8m1-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 25 miles. Two cities are 4.5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["112.5", "100", "125", "90"], correct: 0, explanation: "Goal: convert 4.5 map inches to miles at 1 inch = 25 miles. Multiply inches by the miles-per-inch rate: 4.5 × 25. Compute: 4 × 25 = 100 and 0.5 × 25 = 12.5, so 100 + 12.5 = 112.5 miles (choice A). Check: 112.5/25 = 4.5 inches, the given map distance. Trap: choice C (125) comes from rounding 4.5 up to 5 before multiplying; the half-inch contributes the extra 12.5 miles that must be kept." },
  { id: "t8m1-16", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 3)² = 49 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve for x with the constraint x > 0. Take the square root of both sides, remembering both signs: x + 3 = ±√49 = ±7. Case 1: x + 3 = 7 → x = 4. Case 2: x + 3 = −7 → x = −10. Since x > 0, keep x = 4. Check: (4 + 3)^2 = 7^2 = 49. Trap: dropping the negative root entirely is fine here because the constraint rules out x = −10, but forgetting the constraint and choosing −10, or expanding incorrectly, leads to errors." },
  { id: "t8m1-17", section: "math", domain: "Algebra", difficulty: "med", prompt: "A taxi charges a $3 base fare plus $2 per mile. Which equation gives the cost C for m miles?", type: "mcq", choices: ["C = 2m + 3", "C = 3m + 2", "C = 5m", "C = 2m − 3"], correct: 0, explanation: "Goal: model total cost C for m miles. The per-mile charge ($2) multiplies the number of miles → 2m; the flat $3 base fare is added once → +3. So C = 2m + 3 (choice A). Check: 0 miles costs 2·0 + 3 = $3 (just the base); 1 mile costs $5. Trap: choice B swaps the rate and the base (3m + 2), charging $3 per mile; choice C (5m) merges them into one rate and loses the fixed fee; choice D subtracts the base instead of adding it." },
  { id: "t8m1-18", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² = 6x − 9, what is the value of x?", type: "grid", gridAnswers: ["3"], explanation: "Goal: solve for x. Move all terms to one side: x^2 − 6x + 9 = 0. Recognize a perfect-square trinomial: x^2 − 6x + 9 = (x − 3)^2, so (x − 3)^2 = 0. Therefore x − 3 = 0, giving x = 3 (a repeated root). Check: 3^2 = 9 and 6(3) − 9 = 18 − 9 = 9, so both sides equal 9. Trap: trying to keep two distinct solutions; this trinomial is a perfect square, so x = 3 is the only value." },
  { id: "t8m1-19", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has a perimeter of 30 and a length of 9. What is its width?", type: "mcq", choices: ["6", "5", "12", "21"], correct: 0, explanation: "Goal: find the width given perimeter 30 and length 9. Perimeter of a rectangle = 2(length + width): 2(9 + w) = 30. Divide both sides by 2: 9 + w = 15. Subtract 9: w = 6 (choice A). Check: 2(9 + 6) = 2(15) = 30, the given perimeter. Trap: choice D (21) comes from 30 − 9 (subtracting length from the whole perimeter without dividing by 2); remember the perimeter counts each dimension twice." },
  { id: "t8m1-20", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a class, the ratio of boys to girls is 3 to 5. If there are 24 students total, how many are girls?", type: "mcq", choices: ["15", "9", "12", "18"], correct: 0, explanation: "Goal: count the girls given a 3:5 boys-to-girls ratio and 24 students. Add the ratio parts: 3 + 5 = 8 total parts. Find the value of one part: 24 ÷ 8 = 3 students per part. Girls correspond to 5 parts: 5 × 3 = 15 (choice A). Check: boys = 3 × 3 = 9, and 9 + 15 = 24. Trap: choice B (9) is the number of boys, not girls; reading the ratio in the wrong order or stopping at boys is the common slip." },
  { id: "t8m1-21", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 4y = 24 and x = 2y, what is the value of y?", type: "grid", gridAnswers: ["2.4", "12/5"], explanation: "Goal: solve for y. Use substitution since x = 2y. Replace x in 3x + 4y = 24: 3(2y) + 4y = 24, which becomes 6y + 4y = 24, i.e., 10y = 24. Divide by 10: y = 24/10 = 12/5 = 2.4. Check: then x = 2y = 4.8, and 3(4.8) + 4(2.4) = 14.4 + 9.6 = 24. Trap: forgetting to multiply the whole 3 by 2y (writing 3·2y as 5y or 2y) breaks the combine-like-terms step; 6y + 4y must give 10y." },
  { id: "t8m1-22", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² + 1, what is the value of g(g(2))?", type: "mcq", choices: ["26", "10", "17", "5"], correct: 0, explanation: "Goal: evaluate the composition g(g(2)) where g(x) = x^2 + 1. Work inside out. First g(2) = 2^2 + 1 = 4 + 1 = 5. Then apply g again to that result: g(5) = 5^2 + 1 = 25 + 1 = 26 (choice A). Check: inner value 5, outer 26. Trap: choice D (5) stops after the inner g(2) and forgets the outer application; choice C (17) comes from squaring 4 (=g(2) minus 1) by mistake. Always feed the inner output into the outer function." },
];

// ════════════════════════ MATH — MODULE 2 EASY (22) ════════════════════════
const T8_M_M2E: SatQuestion[] = [
  { id: "t8m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 17, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: isolate x. Subtract 9 from both sides of x + 9 = 17: x = 17 − 9 = 8. Check: 8 + 9 = 17, which matches the equation. Trap: adding instead of subtracting (17 + 9 = 26) reverses the needed operation; to undo '+9' you subtract 9." },
  { id: "t8m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 20% of 60?", type: "mcq", choices: ["12", "6", "20", "40"], correct: 0, explanation: "Goal: compute 20% of 60. Convert the percent to a decimal: 20% = 0.20. Multiply: 0.20 × 60 = 12 (choice A). Check: 10% of 60 is 6, so 20% is double that, 12. Trap: choice C (20) restates the percent figure rather than computing the part; choice D (40) finds the remaining 80% rather than 20%." },
  { id: "t8m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has length 7 and width 4. What is its area?", type: "grid", gridAnswers: ["28"], explanation: "Goal: find the area of a rectangle. Area = length × width = 7 × 4 = 28. Check: 7 rows of 4 unit squares is 28 squares. Trap: computing the perimeter instead, 2(7 + 4) = 22; area multiplies the sides, while perimeter adds them around." },
  { id: "t8m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 42, what is the value of x?", type: "mcq", choices: ["7", "6", "8", "36"], correct: 0, explanation: "Goal: solve 6x = 42. Divide both sides by 6 to isolate x: x = 42 ÷ 6 = 7 (choice A). Check: 6 × 7 = 42, matching the equation. Trap: choice D (36) comes from subtracting (42 − 6) instead of dividing; the coefficient 6 multiplies x, so it is undone by division." },
  { id: "t8m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 4² − 5?", type: "grid", gridAnswers: ["11"], explanation: "Goal: evaluate 4^2 − 5. Follow order of operations: do the exponent first, 4^2 = 16, then subtract: 16 − 5 = 11. Check: 11 + 5 = 16 = 4^2. Trap: doing 4 × 2 = 8 instead of 4^2 = 16 (an exponent means 4·4, not 4·2), which would give the wrong 3." },
  { id: "t8m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 7 of its 10 games. What fraction of its games did it win?", type: "mcq", choices: ["7/10", "3/10", "7/3", "10/7"], correct: 0, explanation: "Goal: express games won as a fraction of games played. The fraction is (games won)/(total games) = 7/10 (choice A). Check: 7/10 of 10 games is 7 wins. Trap: choice B (3/10) is the fraction LOST (10 − 7 = 3 losses), not won; choice D (10/7) flips the fraction, putting total over wins." },
  { id: "t8m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x − 1 = 9, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve for x. Add 1 to both sides of 2x − 1 = 9: 2x = 10. Divide by 2: x = 5. Check: 2(5) − 1 = 10 − 1 = 9, matching. Trap: dividing before adding the 1 (e.g., 9/2) skips a step; the constant must be moved to the right first." },
  { id: "t8m2e-8", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 8 and a height of 5. What is its area?", type: "mcq", choices: ["20", "40", "13", "26"], correct: 0, explanation: "Goal: area of a triangle with base 8 and height 5. Area = (1/2) × base × height = (1/2) × 8 × 5. Compute: 8 × 5 = 40, then half of 40 = 20 (choice A). Check: half of the base-times-height rectangle (40) is 20. Trap: choice B (40) forgets the factor of 1/2 (that's the rectangle's area, not the triangle's); choice C (13) wrongly adds 8 + 5." },
  { id: "t8m2e-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A pencil costs $0.50. How much do 6 pencils cost?", type: "mcq", choices: ["$3.00", "$2.50", "$3.50", "$6.00"], correct: 0, explanation: "Goal: total cost of 6 pencils at $0.50 each. Multiply quantity by unit price: 6 × $0.50 = $3.00 (choice A). Check: two pencils cost $1.00, so six cost three times that, $3.00. Trap: choice D ($6.00) treats each pencil as $1.00; choice B ($2.50) miscounts by one (5 × $0.50). Multiply the count by exactly $0.50." },
  { id: "t8m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 4, what is the value of x?", type: "grid", gridAnswers: ["12"], explanation: "Goal: solve for x. Multiply both sides of x/3 = 4 by 3 to undo the division: x = 4 × 3 = 12. Check: 12/3 = 4, matching. Trap: dividing instead of multiplying (4/3) reverses the operation; since x is divided by 3, you multiply by 3 to isolate it." },
  { id: "t8m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = 2x + 1, what is f(4)?", type: "mcq", choices: ["9", "8", "7", "10"], correct: 0, explanation: "Goal: evaluate f(x) = 2x + 1 at x = 4. Substitute 4 for x: f(4) = 2(4) + 1 = 8 + 1 = 9 (choice A). Check: 2·4 is 8, plus 1 is 9. Trap: choice B (8) forgets the +1 constant; choice C (7) subtracts instead of adds. Apply the multiplication first, then add the constant." },
  { id: "t8m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average (arithmetic mean) of 6, 10, and 14?", type: "grid", gridAnswers: ["10"], explanation: "Goal: find the mean of three numbers. Mean = (sum of values)/(count). Sum: 6 + 10 + 14 = 30. There are 3 values, so divide: 30/3 = 10. Check: 10 sits exactly midway, with 6 four below and 14 four above. Trap: dividing by 2 instead of 3, or forgetting to add all three terms before dividing." },
  { id: "t8m2e-13", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 9. What is its perimeter?", type: "mcq", choices: ["36", "81", "18", "27"], correct: 0, explanation: "Goal: perimeter of a square with side 9. A square has 4 equal sides, so perimeter = 4 × side = 4 × 9 = 36 (choice A). Check: 9 + 9 + 9 + 9 = 36. Trap: choice B (81) computes the AREA (9 × 9), not the perimeter; choice C (18) only doubles the side. Perimeter adds all four sides." },
  { id: "t8m2e-14", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 10 − x = 4, what is the value of x?", type: "mcq", choices: ["6", "4", "14", "5"], correct: 0, explanation: "Goal: solve 10 − x = 4. Add x to both sides: 10 = 4 + x. Subtract 4: x = 10 − 4 = 6 (choice A). Check: 10 − 6 = 4, matching. Trap: choice C (14) comes from adding (10 + 4) instead of subtracting; isolate x by moving it to the positive side first." },
  { id: "t8m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 3 notebooks for $9. At that rate, how much do 5 notebooks cost?", type: "mcq", choices: ["$15", "$12", "$18", "$14"], correct: 0, explanation: "Goal: cost of 5 notebooks at the rate of 3 for $9. Find the unit price: $9 ÷ 3 = $3 per notebook. Then 5 notebooks cost 5 × $3 = $15 (choice A). Check: 3 cost $9 and 2 more cost $6, total $15. Trap: choice B ($12) wrongly adds $3 to $9 (treating it as $9 plus a couple more); set up the rate per item and multiply." },
  { id: "t8m2e-16", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 2³ + 2?", type: "grid", gridAnswers: ["10"], explanation: "Goal: evaluate 2^3 + 2. Order of operations: exponent first, 2^3 = 2·2·2 = 8, then add: 8 + 2 = 10. Check: 10 − 2 = 8 = 2^3. Trap: computing 2 × 3 = 6 instead of 2^3 = 8 (the exponent means three 2's multiplied, not 2 times 3)." },
  { id: "t8m2e-17", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "Two angles of a triangle are 90° and 30°. What is the third angle, in degrees?", type: "mcq", choices: ["60", "30", "90", "120"], correct: 0, explanation: "Goal: find the third angle. A triangle's interior angles sum to 180°. Add the known angles: 90 + 30 = 120. Subtract from 180: 180 − 120 = 60° (choice A). Check: 90 + 30 + 60 = 180. Trap: choice D (120) is the sum of the two known angles, not the remaining angle; you must subtract that sum from 180." },
  { id: "t8m2e-18", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 6 = 18, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve for x. Subtract 6 from both sides of 3x + 6 = 18: 3x = 12. Divide by 3: x = 4. Check: 3(4) + 6 = 12 + 6 = 18, matching. Trap: dividing 18 by 3 before removing the 6 (giving 6) skips the subtraction step; clear the constant first." },
  { id: "t8m2e-19", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "Out of 50 students, 30 ride the bus. What percent ride the bus?", type: "mcq", choices: ["60%", "30%", "50%", "20%"], correct: 0, explanation: "Goal: percent of 50 students who ride the bus, given 30 do. Percent = (part)/(whole) × 100 = (30/50) × 100. Compute 30/50 = 0.60, so 0.60 × 100 = 60% (choice A). Check: 60% of 50 = 0.60 × 50 = 30 riders. Trap: choice B (30%) just restates the count 30 as a percent; choice D (20%) finds the non-riders' fraction (20/50). Divide the part by the whole." },
  { id: "t8m2e-20", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 5x = 3x + 8, what is the value of x?", type: "mcq", choices: ["4", "2", "8", "6"], correct: 0, explanation: "Goal: solve 5x = 3x + 8. Subtract 3x from both sides to gather x-terms: 5x − 3x = 8, so 2x = 8. Divide by 2: x = 4 (choice A). Check: 5(4) = 20 and 3(4) + 8 = 12 + 8 = 20; both sides equal 20. Trap: choice C (8) forgets to divide by 2 after combining; 2x = 8 still requires dividing by the coefficient." },
  { id: "t8m2e-21", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a diameter of 14. What is its radius?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find the radius from the diameter. The radius is half the diameter: r = d/2 = 14/2 = 7. Check: doubling the radius, 2 × 7 = 14, recovers the diameter. Trap: multiplying by 2 (28) instead of dividing reverses the relationship; the radius is always the smaller, half value." },
  { id: "t8m2e-22", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If x² = 49 and x > 0, what is the value of x?", type: "mcq", choices: ["7", "49", "6", "14"], correct: 0, explanation: "Goal: solve x^2 = 49 with x > 0. Take the square root of both sides: x = ±√49 = ±7. The constraint x > 0 keeps the positive root, x = 7 (choice A). Check: 7^2 = 49. Trap: choice B (49) leaves the value squared rather than taking the root; choice D (14) doubles 7 instead of square-rooting. The square root, not division by 2, undoes the square." },
];

// ════════════════════════ MATH — MODULE 2 HARD (22) ════════════════════════
const T8_M_M2H: SatQuestion[] = [
  { id: "t8m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 5x + 6 = 0, what is the product of the solutions?", type: "grid", gridAnswers: ["6"], explanation: "Goal: product of the roots. Factor x^2 − 5x + 6: two numbers multiplying to +6 and adding to −5 are −2 and −3, so (x − 2)(x − 3) = 0. Roots are x = 2 and x = 3; product = 2 × 3 = 6. Shortcut/check: for x^2 + bx + c = 0, the product of roots equals c, and here c = 6, confirming it. Trap: reporting the sum (2 + 3 = 5) instead of the product, or sign-confusing c." },
  { id: "t8m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 3y = 27 and 2x − y = 1, what is the value of x?", type: "mcq", choices: ["3", "4", "5", "2"], correct: 0, explanation: "Goal: solve the system 4x + 3y = 27 and 2x − y = 1 for x. Solve the second equation for y: 2x − y = 1 → y = 2x − 1. Substitute into the first: 4x + 3(2x − 1) = 27 → 4x + 6x − 3 = 27 → 10x − 3 = 27. Add 3: 10x = 30. Divide: x = 3 (choice A). Check: y = 2(3) − 1 = 5, and 4(3) + 3(5) = 12 + 15 = 27. Trap: forgetting to distribute the 3 over both terms of (2x − 1), which would mis-combine the x-terms." },
  { id: "t8m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x+1) = 81, what is the value of x?", type: "grid", gridAnswers: ["3"], explanation: "Goal: solve 3^(x+1) = 81. Write 81 as a power of 3: 3, 9, 27, 81 → 3^1, 3^2, 3^3, 3^4, so 81 = 3^4. With equal bases, set the exponents equal: x + 1 = 4. Subtract 1: x = 3. Check: 3^(3+1) = 3^4 = 81. Trap: forgetting the '+1' in the exponent and answering x = 4 (which is the full exponent, not x); the exponent is x + 1, so subtract 1 at the end." },
  { id: "t8m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of bacteria doubles every hour. If it starts at 200, how many are there after 4 hours?", type: "mcq", choices: ["3200", "1600", "800", "2400"], correct: 0, explanation: "Goal: bacteria after 4 hours, doubling hourly from 200. Exponential growth: final = initial × 2^(number of doublings) = 200 × 2^4. Compute 2^4 = 16, then 200 × 16 = 3200 (choice A). Check by stepping: 200 → 400 → 800 → 1600 → 3200 over 4 hours. Trap: choice B (1600) stops one hour early (only 3 doublings); choice D (2400) wrongly multiplies 200 by 12 or adds. Count exactly 4 doublings." },
  { id: "t8m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has a hypotenuse of 13 and one leg of 5. What is the length of the other leg?", type: "grid", gridAnswers: ["12"], explanation: "Goal: find the missing leg using a^2 + b^2 = c^2, where c = 13 is the hypotenuse. Solve for the leg b: b^2 = c^2 − a^2 = 13^2 − 5^2 = 169 − 25 = 144. Take the positive root: b = √144 = 12. Check: 5-12-13 is a classic Pythagorean triple. Trap: adding instead of subtracting (13^2 + 5^2) treats the hypotenuse as a leg; since 13 is the hypotenuse, you SUBTRACT the known leg's square." },
  { id: "t8m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The function h(x) = 2x² − 8x + 6 has its minimum at which x-value?", type: "mcq", choices: ["2", "4", "−2", "1"], correct: 0, explanation: "Goal: x-coordinate of the minimum of h(x) = 2x^2 − 8x + 6. For a parabola ax^2 + bx + c opening upward (a = 2 > 0), the minimum is at the vertex x = −b/(2a). Here a = 2, b = −8: x = −(−8)/(2·2) = 8/4 = 2 (choice A). Check: the axis of symmetry x = 2 is where the minimum sits. Trap: choice C (−2) drops the sign change in −b; since b = −8, −b = +8, giving a positive x. Apply −b carefully." },
  { id: "t8m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −2 and passes through (1, 5). What is its y-intercept?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find b in y = mx + b given slope m = −2 and point (1, 5). Plug the point into the equation: 5 = −2(1) + b, so 5 = −2 + b. Add 2 to both sides: b = 7. The y-intercept is 7. Check: y = −2x + 7 gives y = −2(1) + 7 = 5 at x = 1. Trap: dropping the negative on the slope (using +2) would give b = 3; keep the sign of the slope when substituting." },
  { id: "t8m2h-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A $120 item increases in price by 15%, then decreases by 10%. What is the final price?", type: "mcq", choices: ["$124.20", "$126.00", "$120.00", "$132.00"], correct: 0, explanation: "Goal: final price after a 15% increase then a 10% decrease on $120. Apply the increase: a +15% means multiplying by 1.15, so 120 × 1.15 = 138. Apply the decrease: a −10% means multiplying by 0.90, so 138 × 0.90 = 124.20 (choice A). Check: 138 − 10% of 138 (13.80) = 124.20. Trap: choice C ($120) assumes +15% and −10% cancel — they don't, because the 10% is taken off the larger $138, not the original $120. Net change is +1.15·0.90 = 1.035, a 3.5% gain." },
  { id: "t8m2h-9", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If (x − 4)(x + 2) = 0, what is the sum of the solutions?", type: "grid", gridAnswers: ["2"], explanation: "Goal: sum of the roots. By the zero-product property, set each factor to 0: x − 4 = 0 → x = 4, and x + 2 = 0 → x = −2. Sum = 4 + (−2) = 2. Check: expanding gives x^2 − 2x − 8, where sum of roots = −b = −(−2) = 2, confirming. Trap: reading the factors' constants directly as roots (4 and 2 with wrong signs) — the root from (x + 2) is −2, not +2, so the signs flip." },
  { id: "t8m2h-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the angle θ has sin θ = 3/5. What is cos θ?", type: "mcq", choices: ["4/5", "5/4", "3/4", "5/3"], correct: 0, explanation: "Goal: find cos θ given sin θ = 3/5 in a right triangle. Sine = opposite/hypotenuse, so opposite = 3 and hypotenuse = 5. Find the adjacent leg with the Pythagorean theorem: adjacent = √(5^2 − 3^2) = √(25 − 9) = √16 = 4 (a 3-4-5 triangle). Cosine = adjacent/hypotenuse = 4/5 (choice A). Check: sin^2 + cos^2 = (3/5)^2 + (4/5)^2 = 9/25 + 16/25 = 1. Trap: choice B (5/4) and D (5/3) invert ratios (put hypotenuse on top); cosine must be a side over the hypotenuse, so the value is less than 1." },
  { id: "t8m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2/x = 3/(x + 5), what is the value of x?", type: "grid", gridAnswers: ["10"], explanation: "Goal: solve the proportion. Cross-multiply 2/x = 3/(x + 5): 2(x + 5) = 3x. Distribute the left side: 2x + 10 = 3x. Subtract 2x from both sides: 10 = x, so x = 10. Check: 2/10 = 1/5 and 3/(10 + 5) = 3/15 = 1/5; both equal 1/5. Trap: cross-multiplying incorrectly (e.g., 2(x) = 3(x + 5)) pairs the wrong terms; multiply each numerator by the OTHER fraction's denominator." },
  { id: "t8m2h-12", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 36 with a < 0, what is a?", type: "mcq", choices: ["−6", "6", "−18", "−36"], correct: 0, explanation: "Goal: find a given f(x) = x^2, f(a) = 36, and a < 0. Set up the equation: a^2 = 36. Take both square roots: a = ±6. The constraint a < 0 selects the negative root, a = −6 (choice A). Check: (−6)^2 = 36. Trap: choice B (6) is the positive root, which violates a < 0; choice D (−36) forgets to take the square root and just negates 36. The square root of 36 is 6, then apply the sign condition." },
  { id: "t8m2h-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The mean of 5 numbers is 14. If one number is removed and the mean of the remaining 4 is 12, what was the removed number?", type: "grid", gridAnswers: ["22"], explanation: "Goal: find the removed number. Use sum = mean × count for each set. Original total: 5 × 14 = 70. Total of the remaining 4: 4 × 12 = 48. The removed number is the difference between the two totals: 70 − 48 = 22. Check: if the four remaining numbers sum to 48 and we add back 22, we get 70, with mean 70/5 = 14. Trap: subtracting the means (14 − 12 = 2) instead of the sums; you must reconstruct the totals first." },
  { id: "t8m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 3 and height 5. What is its volume? (Use π.)", type: "mcq", choices: ["45π", "30π", "75π", "15π"], correct: 0, explanation: "Goal: volume of a cylinder with radius 3 and height 5. Volume = πr^2h. Square the radius: r^2 = 3^2 = 9. Multiply by height: 9 × 5 = 45. So V = 45π (choice A). Check: the base area is πr^2 = 9π, times height 5 = 45π. Trap: choice D (15π) uses r instead of r^2 (3 × 5 = 15), forgetting to square the radius; the base area requires r^2." },
  { id: "t8m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If |2x − 3| = 7 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve the absolute-value equation with x > 0. An absolute value splits into two cases: 2x − 3 = 7 OR 2x − 3 = −7. Case 1: 2x = 10 → x = 5. Case 2: 2x = −4 → x = −2. The constraint x > 0 keeps x = 5. Check: |2(5) − 3| = |10 − 3| = |7| = 7. Trap: solving only one case and missing that absolute value yields two equations, or choosing x = −2 despite the x > 0 requirement." },
  { id: "t8m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the value of x that satisfies √(x + 7) = 4?", type: "mcq", choices: ["9", "16", "3", "23"], correct: 0, explanation: "Goal: solve √(x + 7) = 4. Eliminate the radical by squaring both sides: (√(x + 7))^2 = 4^2, so x + 7 = 16. Subtract 7: x = 9 (choice A). Check: √(9 + 7) = √16 = 4, matching. Trap: choice B (16) stops after squaring and forgets to subtract the 7; choice D (23) adds 7 instead of subtracting. After squaring, isolate x by removing the +7." },
  { id: "t8m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A car travels 150 miles in 2.5 hours. At this rate, how far will it travel in 4 hours?", type: "mcq", choices: ["240 miles", "200 miles", "375 miles", "180 miles"], correct: 0, explanation: "Goal: distance in 4 hours at a constant rate. First find the speed: rate = distance/time = 150/2.5 = 60 mph. Then distance = rate × time = 60 × 4 = 240 miles (choice A). Check: at 60 mph, 4 hours covers 4 × 60 = 240. Trap: choice C (375) wrongly multiplies 150 × 2.5 instead of dividing to get the rate; first reduce to a per-hour rate, then scale to 4 hours." },
  { id: "t8m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 2:3. If the smaller has area 8, what is the area of the larger?", type: "grid", gridAnswers: ["18"], explanation: "Goal: area of the larger triangle. Key rule: for similar figures, areas scale by the SQUARE of the linear scale factor. Going from the smaller (2) to the larger (3), the linear factor is 3/2, so the area factor is (3/2)^2 = 9/4. Multiply the smaller area: 8 × 9/4 = 72/4 = 18. Check: 18/8 = 9/4 = (3/2)^2. Trap: multiplying area by the linear factor 3/2 (giving 12) instead of squaring it; area scales by the factor squared, not the factor itself." },
  { id: "t8m2h-19", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3(2x − 1) − 2(x + 4) = 5, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve for x. Distribute carefully: 3(2x − 1) = 6x − 3, and −2(x + 4) = −2x − 8 (the negative applies to both terms). The equation becomes 6x − 3 − 2x − 8 = 5. Combine like terms: (6x − 2x) + (−3 − 8) = 4x − 11, so 4x − 11 = 5. Add 11: 4x = 16. Divide by 4: x = 4. Check: 3(2·4 − 1) − 2(4 + 4) = 3(7) − 2(8) = 21 − 16 = 5. Trap: distributing −2 as −2x + 8 (forgetting to negate the +4) is the most common sign error." },
  { id: "t8m2h-20", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + 6x + c is a perfect square trinomial, what is the value of c?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find c that makes x^2 + 6x + c a perfect square. A perfect square trinomial has the form (x + p)^2 = x^2 + 2px + p^2. Match the middle term: 2p = 6, so p = 3. Then the constant is c = p^2 = 3^2 = 9. (Equivalently, c = (6/2)^2 = 9.) Check: x^2 + 6x + 9 = (x + 3)^2. Trap: setting c = 6 (the coefficient itself) or 36 (squaring 6 without halving); you must halve the x-coefficient first, then square." },
  { id: "t8m2h-21", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A survey of 200 people found 35% preferred tea. How many people preferred tea?", type: "mcq", choices: ["70", "65", "75", "35"], correct: 0, explanation: "Goal: how many of 200 people preferred tea, given 35%. Convert the percent to a decimal and multiply by the total: 0.35 × 200 = 70 (choice A). Check: 10% of 200 is 20, so 35% is 3.5 × 20 = 70. Trap: choice D (35) restates the percentage as a count instead of applying it to 200; you must multiply the percent by the group size." },
  { id: "t8m2h-22", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If the parabola y = x² − 4x + 1 has its vertex at (h, k), what is k?", type: "grid", gridAnswers: ["-3"], explanation: "Goal: the y-coordinate k of the vertex of y = x^2 − 4x + 1. First find h, the axis of symmetry: h = −b/(2a) = −(−4)/(2·1) = 4/2 = 2. Then k is the function value at x = h: k = (2)^2 − 4(2) + 1 = 4 − 8 + 1 = −3. Check: completing the square, y = (x − 2)^2 − 3, so the vertex is (2, −3). Trap: stopping at h = 2 and reporting that as k; the question asks for k, which requires plugging h back into the equation." },
];

